def transform(grid):
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    for row in out:
        cells = [v for v in row if v != bg]
        if cells and len(cells) < len(row) and len(set(cells)) == 1:
            for j, v in enumerate(row):
                if v == bg:
                    row[j] = 1
    return out
